svg.script:
(function(){
  var items = document.querySelectorAll('.legend-item');
  for (var i = 0; i < items.length; i++) {
    items[i].addEventListener('click', function() {
      var targets = this.getAttribute('data-target').split(' ');
      for (var j = 0; j < targets.length; j++) {
        var el = document.getElementById(targets[j]);
        if (el) {
          var cur = el.getAttribute('display');
          el.setAttribute('display', cur === 'none' ? 'inline' : 'none');
        }
      }
      this.classList.toggle('dimmed');
    });
  }
})();
